const CACHE='vasra-v9-officers';const ASSETS=['./','./index.html','./projects.html','./home.css','./home.js','./officers.js','./officers.css','./duty-data.js','./style.css','./modern.css','./portal.css','./shell.js','./duty.html','./contacts.html','./transparency.html','./transparency.js','./duty.js','./common.js','./app.js','./sk.png','./sk%20logo.jpg','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('vasra-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||u.pathname.startsWith('/api/')||u.pathname.endsWith('/account.html')||u.pathname.endsWith('/account.js'))return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
